// Helper dua digit (01, 02, dst)
const pad = (n) => String(n).padStart(2, '0');

// 1. Tanggal Hari Ini (End Date)
const now = new Date();
const endYear = now.getFullYear();
const endMonth = pad(now.getMonth() + 1);
const endDate = pad(now.getDate());

// 2. Tanggal 15 Hari Lalu (Start Date)
const past = new Date(now.getTime() - (15 * 24 * 60 * 60 * 1000));
const startYear = past.getFullYear();
const startMonth = pad(past.getMonth() + 1);
const startDate = pad(past.getDate());

// 3. Waktu Mulai Jadwal SAP (Sekarang + 1 Menit)
const schedTimeObj = new Date(now.getTime() + (1 * 60 * 1000));
const schedHour = pad(schedTimeObj.getHours());
const schedMin = pad(schedTimeObj.getMinutes());

// Format YYYY-MM-DD
const end_date_ymd = `${endYear}-${endMonth}-${endDate}`;
const start_date_ymd = `${startYear}-${startMonth}-${startDate}`;

// Format dd.MM.yyyy untuk SM37
const end_date_dmy = `${endDate}.${endMonth}.${endYear}`;
const start_date_dmy = `${startDate}.${startMonth}.${startYear}`;

const sched_start_time = `${schedHour}:${schedMin}`;

return [{
  json: {
    start_date_ymd,
    end_date_ymd,
    start_date_dmy,
    end_date_dmy,
    sched_start_date: end_date_ymd,
    sched_start_time,
    chunk_days: 15
  }
}];
